-- Only unload previous Lua X UI (don't fight Unnamed Enhancements / other libs)
local OldLibrary = getgenv().LuaXLibrary or getgenv().Library;
if type(OldLibrary) == 'table' and OldLibrary.ScreenGui then
    local n = tostring(OldLibrary.ScreenGui.Name or '')
    if n:find('LuaX') or OldLibrary._IsLuaX then
        pcall(function()
            if OldLibrary.Unload then OldLibrary:Unload(); end
            if OldLibrary.ScreenGui then OldLibrary.ScreenGui:Destroy(); end
        end)
    end
end

