            });
            local Container = Library:Create('Frame', {
                BackgroundTransparency = 1;
                Position = UDim2.new(0, 4, 0, 20);
                Size = UDim2.new(1, -4, 1, -20);
                ZIndex = 1;
                Parent = BoxInner;
            });
            Library:Create('UIListLayout', {
                FillDirection = Enum.FillDirection.Vertical;
                SortOrder = Enum.SortOrder.LayoutOrder;
                Parent = Container;
            });
            function Groupbox:Resize()
                local Size = 0;
                for _, Element in next, Groupbox.Container:GetChildren() do
                    if (not Element:IsA('UIListLayout')) and Element.Visible then
                        Size = Size + Element.Size.Y.Offset;
                    end;
                end;

                BoxOuter.Size = UDim2.new(1, 0, 0, 20 + Size + 2 + 2);
            end;

            Groupbox.Container = Container;
            setmetatable(Groupbox, BaseGroupbox);
            Groupbox:AddBlank(3);
            Groupbox:Resize();

            Tab.Groupboxes[Info.Name] = Groupbox;

            return Groupbox;
        end;

        function Tab:AddLeftGroupbox(Name)
            return Tab:AddGroupbox({ Side = 1; Name = Name; });
        end;

        function Tab:AddRightGroupbox(Name)
            return Tab:AddGroupbox({ Side = 2; Name = Name; });
        end;

        function Tab:AddTabbox(Info)
            local Tabbox = {
                Tabs = {};
            };

            local BoxOuter = Library:Create('Frame', {
                BackgroundColor3 = Library.BackgroundColor;
                BorderColor3 = Library.OutlineColor;
                BorderMode = Enum.BorderMode.Inset;
                Size = UDim2.new(1, 0, 0, 0);
                ZIndex = 2;
                Parent = Info.Side == 1 and LeftSide or RightSide;
            });
            Library:AddToRegistry(BoxOuter, {
                BackgroundColor3 = 'BackgroundColor';
                BorderColor3 = 'OutlineColor';
            });
            local BoxInner = Library:Create('Frame', {
                BackgroundColor3 = Library.BackgroundColor;
                BorderColor3 = Color3.new(0, 0, 0);
                Size = UDim2.new(1, -2, 1, -2);
                Position = UDim2.new(0, 1, 0, 1);
                ZIndex = 4;
                Parent = BoxOuter;
            });
            Library:AddToRegistry(BoxInner, {
                BackgroundColor3 = 'BackgroundColor';
            });
            local TabboxButtons = Library:Create('Frame', {
                BackgroundTransparency = 1;
                Position = UDim2.new(0, 0, 0, 1);
                Size = UDim2.new(1, 0, 0, 18);
                ZIndex = 5;
                Parent = BoxInner;
            });
            Library:Create('UIListLayout', {
                FillDirection = Enum.FillDirection.Horizontal;
                HorizontalAlignment = Enum.HorizontalAlignment.Left;
                SortOrder = Enum.SortOrder.LayoutOrder;
                Parent = TabboxButtons;
            });
            function Tabbox:AddTab(Name)
                local Tab = {};
                local Button = Library:Create('Frame', {
                    BackgroundColor3 = Library.MainColor;
                    BorderColor3 = Color3.new(0, 0, 0);
                    Size = UDim2.new(0.5, 0, 1, 0);
                    ZIndex = 6;
                    Parent = TabboxButtons;
                });
                Library:AddToRegistry(Button, {
                    BackgroundColor3 = 'MainColor';
                });
                local TabHighlight = Library:Create('Frame', {
                    BackgroundColor3 = Library.AccentColor;
                    BorderSizePixel = 0;
                    Size = UDim2.new(1, 0, 0, 2);
                    Visible = false;
                    ZIndex = 10;
                    Parent = Button;
                });
                Library:AddToRegistry(TabHighlight, {
                    BackgroundColor3 = 'AccentColor';
                });
                local ButtonLabel = Library:CreateLabel({
                    Size = UDim2.new(1, 0, 1, 0);
                    TextSize = Library.FontSize;
                    Text = Name;
                    TextXAlignment = Enum.TextXAlignment.Center;
                    ZIndex = 7;
                    Parent = Button;
                });
                local Block = Library:Create('Frame', {
                    BackgroundColor3 = Library.BackgroundColor;
                    BorderSizePixel = 0;
                    Position = UDim2.new(0, 0, 1, 0);
                    Size = UDim2.new(1, 0, 0, 1);
                    Visible = false;
                    ZIndex = 9;
                    Parent = Button;
                });
                Library:AddToRegistry(Block, {
                    BackgroundColor3 = 'BackgroundColor';
                });
                local Container = Library:Create('Frame', {
                    BackgroundTransparency = 1;
                    Position = UDim2.new(0, 4, 0, 20);
                    Size = UDim2.new(1, -4, 1, -20);
                    ZIndex = 1;
                    Visible = false;
                    Parent = BoxInner;
                });
                Library:Create('UIListLayout', {
                    FillDirection = Enum.FillDirection.Vertical;
                    SortOrder = Enum.SortOrder.LayoutOrder;
                    Parent = Container;
                });
                function Tab:Show()
                    for _, Tab in next, Tabbox.Tabs do
                        Tab:Hide();
                    end;

                    Container.Visible = true;
                    Block.Visible = true;
                    TabHighlight.Visible = true;

                    Button.BackgroundColor3 = Library.BackgroundColor;
                    Library.RegistryMap[Button].Properties.BackgroundColor3 = 'BackgroundColor';

                    Tab:Resize();
                end;
                function Tab:Hide()
                    Container.Visible = false;
                    Block.Visible = false;
                    TabHighlight.Visible = false;

                    Button.BackgroundColor3 = Library.MainColor;
                    Library.RegistryMap[Button].Properties.BackgroundColor3 = 'MainColor';
                end;
                function Tab:Resize()
                    local TabCount = 0;
                    for _, Tab in next, Tabbox.Tabs do
                        TabCount = TabCount + 1;
                    end;

                    for _, Button in next, TabboxButtons:GetChildren() do
                        if not Button:IsA('UIListLayout') then
                            Button.Size = UDim2.new(1 / TabCount, 0, 1, 0);
                        end;
                    end;

                    if (not Container.Visible) then
                        return;
                    end;

                    local Size = 0;

                    for _, Element in next, Tab.Container:GetChildren() do
                        if (not Element:IsA('UIListLayout')) and Element.Visible then
                            Size = Size + Element.Size.Y.Offset;
                        end;
                    end;

                    BoxOuter.Size = UDim2.new(1, 0, 0, 20 + Size + 2 + 2);
                end;
                Button.InputBegan:Connect(function(Input)
                    if (Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch) and not Library:MouseIsOverOpenedFrame() then
                        Tab:Show();
                        Tab:Resize();
                    end;
                end);

                Tab.Container = Container;
                Tabbox.Tabs[Name] = Tab;

                setmetatable(Tab, BaseGroupbox);

                Tab:AddBlank(3);
                Tab:Resize();

                if #TabboxButtons:GetChildren() == 2 then
                    Tab:Show();
                end;

                return Tab;
            end;

            Tab.Tabboxes[Info.Name or ''] = Tabbox;

            return Tabbox;
        end;
        function Tab:AddLeftTabbox(Name)
            return Tab:AddTabbox({ Name = Name, Side = 1; });
        end;

        function Tab:AddRightTabbox(Name)
            return Tab:AddTabbox({ Name = Name, Side = 2; });
        end;

        TabButton.InputBegan:Connect(function(Input)
            if (Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch) then
                pcall(function() Library:PlaySound("Tab", 0.25) end)
                Tab:ShowTab();
            end;
        end);
        if #TabContainer:GetChildren() == 1 then
            Tab:ShowTab();
        end;
        Window.Tabs[Name] = Tab;
        return Tab;
    end;

    local ModalElement = Library:Create('TextButton', {
        BackgroundTransparency = 1;
        Size = UDim2.new(0, 0, 0, 0);
        Visible = true;
        Text = '';
        Modal = false;
        Parent = ScreenGui;
    });
    function Library:Toggle()
        if Library._AnimLock then return end
        local opening = not Library.Toggled
        Library.Toggled = opening
        ModalElement.Modal = opening

        local FadeTime = typeof(Config.MenuFadeTime) == 'number' and Config.MenuFadeTime or 0.18
        local fullSize = Config.Size

        if opening then
            Library._AnimLock = true
            Outer.Visible = true
            local glassT = (Library.GlassEnabled ~= false) and (Library.OuterGlassTransparency or Library._GlassLayer1 or 0.65) or 0
            Outer.Size = UDim2.fromOffset(
                math.max(50, fullSize.X.Offset * 0.96),
                math.max(50, fullSize.Y.Offset * 0.96)
            )
            Outer.BackgroundTransparency = math.min(0.9, glassT + 0.15)
            local tIn = TweenService:Create(Outer, TweenInfo.new(FadeTime, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                Size = fullSize;
                BackgroundTransparency = glassT;
            })
            tIn:Play()
            tIn.Completed:Connect(function()
                Outer.Size = fullSize
                Outer.BackgroundTransparency = glassT
                pcall(function() Library:ReapplyGlass() end)
                Library._AnimLock = false
            end)

            task.spawn(function()
                -- Use single StartCustomCursor (no second mouse)
                if Library.StartCustomCursor then
                    Library:StartCustomCursor()
                    return
                end
                if Library.ShowCustomCursor == false then return end
                local State = InputService.MouseIconEnabled
                local GuiService = game:GetService("GuiService")
                local Cursor = Instance.new("ImageLabel")
                Cursor.Name = "RCLR_CustomCursor"
                Cursor.Image = "rbxassetid://4292970642"
                Cursor.BackgroundTransparency = 1
                Cursor.ZIndex = 100
                Cursor.Size = UDim2.fromOffset(17, 17)
                Cursor.Rotation = -45
                Cursor.Parent = ScreenGui
                local acc = 0
                local conn
                conn = RunService.Heartbeat:Connect(function(dt)
                    if not Library.Toggled or not ScreenGui.Parent then
                        if conn then conn:Disconnect() end
                        InputService.MouseIconEnabled = State
                        if Cursor then Cursor:Destroy() end
                        return
                    end
                    acc = acc + dt
                    if acc < 0.016 then return end -- ~60fps max, skip extra work
                    acc = 0
                    InputService.MouseIconEnabled = false
                    local mPos = InputService:GetMouseLocation()
                    Cursor.ImageColor3 = Library.AccentColor
                    Cursor.Position = UDim2.fromOffset(mPos.X, mPos.Y - GuiService:GetGuiInset().Y - 1)
                end)
                table.insert(Library.Signals, conn)
            end)
        else
            -- Premium close: fade + scale down (human feel)
            Library._AnimLock = true
            local glassT = (Library.GlassEnabled ~= false) and (Library.OuterGlassTransparency or Library._GlassLayer1 or 0.65) or 0
            local tOut = TweenService:Create(Outer, TweenInfo.new(math.max(FadeTime, 0.28), Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
                Size = UDim2.fromOffset(
                    math.max(36, fullSize.X.Offset * 0.90),
                    math.max(36, fullSize.Y.Offset * 0.90)
                );
                BackgroundTransparency = math.min(0.98, glassT + 0.45);
            })
            tOut:Play()
            tOut.Completed:Connect(function()
                Outer.Visible = false
                Outer.Size = fullSize
                Outer.BackgroundTransparency = glassT
                Library._AnimLock = false
            end)
        end
        Library:UpdateBlur()
    end

    Library:GiveSignal(InputService.InputBegan:Connect(function(Input, Processed)
        -- Menu toggle key (always uses CURRENT ToggleKeybind.Value)
        if Processed then return end
        local kb = Library.ToggleKeybind
        local val = 'RightControl'
        if type(kb) == 'table' then
            -- KeyPicker object
            if kb.Value ~= nil then
                val = tostring(kb.Value)
            elseif kb.Key ~= nil then
                val = tostring(kb.Key)
            end
        elseif type(kb) == 'string' then
            val = kb
        end
        -- normalize
        if val == 'Right Control' then val = 'RightControl' end
        if val == 'Left Control' then val = 'LeftControl' end
        local match = false
        if Input.UserInputType == Enum.UserInputType.Keyboard then
            match = (Input.KeyCode.Name == val)
        elseif (val == 'MB1' or val == 'MouseButton1') and Input.UserInputType == Enum.UserInputType.MouseButton1 then
            match = true
        elseif (val == 'MB2' or val == 'MouseButton2') and Input.UserInputType == Enum.UserInputType.MouseButton2 then
            match = true
        end
        if match then
            task.spawn(function()
                Library:Toggle()
            end)
        end
    end))

    -- When script sets ToggleKeybind to a KeyPicker, keep listening to Value changes
    task.defer(function()
        local last = nil
        Library:GiveSignal(RunService.Heartbeat:Connect(function()
            local kb = Library.ToggleKeybind
            if type(kb) == 'table' and kb.Value ~= nil and kb.Value ~= last then
                last = kb.Value
            end
        end))
    end)

    -- Reliable AutoShow (force visible so UI always appears)
    if Config.AutoShow then
        pcall(function()
            Library.Toggled = true
            Library._AnimLock = false
            Outer.Visible = true
            Outer.Size = Config.Size
            local glassT = (Library.GlassEnabled ~= false) and (Library.OuterGlassTransparency or Library._GlassLayer1 or 0.55) or 0
            Outer.BackgroundTransparency = glassT
            if ModalElement then ModalElement.Modal = true end
            pcall(function() Library:ReapplyGlass() end)
            pcall(function() Library:UpdateBlur() end)
            pcall(function() if Library.StartCustomCursor then Library:StartCustomCursor() end end)
            pcall(function()
                if not Library._LogoGui then Library:CreateLogo({ Text = "RCLR" }) end
                Library:UpdateLogoVisibility()
            end)
        end)
        task.defer(function()
            pcall(function()
                if not Outer.Visible then
                    Outer.Visible = true
                    Library.Toggled = true
                end
                if Library.StartCustomCursor then Library:StartCustomCursor() end
            end)
        end)
    end

    Outer.Active = true
    if Inner then Inner.Active = true end
    Window.Holder = Outer;
    Library.ActiveWindow = Window
    return Window;
end;

local function OnPlayerChange()
    local PlayerList = GetPlayersString();
    for _, Value in next, Options do
        if Value.Type == 'Dropdown' and Value.SpecialType == 'Player' then
            Value:SetValues(PlayerList);
        end;
    end;
end;

Players.PlayerAdded:Connect(OnPlayerChange);
Players.PlayerRemoving:Connect(OnPlayerChange);

-- Mobile / touch UI (works on executor mobile + tablet)
local _IsMobile = InputService.TouchEnabled or (not InputService.KeyboardEnabled)
if _IsMobile then
    local MobileGui = Instance.new("ScreenGui")
    MobileGui.Name = "LinoriaMobileUI"
    MobileGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    ProtectGui(MobileGui)
    MobileGui.Parent = CoreGui

    local BTN_W, BTN_H = 88, 30
    local BTN_GAP      = 40  

    local function CreateMobileButton(name, text, startPos)
        -- Classic Linoria-style mobile button (black box + white border)
        local Outer = Library:Create('Frame', {
            Name = name .. "Outer",
            BackgroundColor3 = Color3.fromRGB(20, 20, 20),
            BorderColor3 = Color3.fromRGB(255, 255, 255),
            BorderSizePixel = 1,
            Position = startPos,
            Size = UDim2.new(0, 90, 0, 28),
            ZIndex = 300,
            Parent = MobileGui,
            Active = true,
        })
        local Btn = Library:Create('TextButton', {
            Name = name .. "Btn",
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 1, 0),
            Font = Enum.Font.Code,
            Text = text,
            TextColor3 = Color3.fromRGB(255, 255, 255),
            TextSize = 13,
            ZIndex = 301,
            Parent = Outer,
            Active = true,
        })
        return Outer, Btn
    end

    local ToggleOuter, ToggleBtn = CreateMobileButton("Toggle", "Toggle UI",  UDim2.new(0, 10, 0, 10))
    local LockOuter,   LockBtn  = CreateMobileButton("Lock",   "Unlock UI",  UDim2.new(0, 10, 0, 10 + BTN_H + (BTN_GAP - BTN_H)))

    local IsUnlocked = false

    local function BindMobileButtonAction(Btn, Outer, ClickAction)
        local dragging  = false
        local dragInput = nil
        local dragStart = nil
        local startPos  = nil
        local hasMoved  = false

        Btn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                dragging  = true
                hasMoved  = false
                dragStart = input.Position
                startPos  = Outer.Position
                dragInput = input

                local connection
                connection = input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                        connection:Disconnect()
                        if not hasMoved then
                            ClickAction()
                        end
                    end
                end)
            end
        end)

        InputService.InputChanged:Connect(function(input)
            if input == dragInput and dragging then
                local delta = input.Position - dragStart
                if delta.Magnitude > 3 then
                    hasMoved = true
                end
                if IsUnlocked and hasMoved then
                    Outer.Position = UDim2.new(
                        startPos.X.Scale, startPos.X.Offset + delta.X,
                        startPos.Y.Scale, startPos.Y.Offset + delta.Y
                    )
                end
            end
        end)
    end

    BindMobileButtonAction(ToggleBtn, ToggleOuter, function()
        Library:Toggle()
    end)

    BindMobileButtonAction(LockBtn, LockOuter, function()
        IsUnlocked = not IsUnlocked
        LockBtn.Text = IsUnlocked and "Lock UI" or "Unlock UI"
        LockBtn.TextColor3 = IsUnlocked
            and Library.AccentColor
            or  Color3.fromRGB(255, 255, 255)
    end)

    local _origUpdate = Library.UpdateColorsUsingRegistry
    Library.UpdateColorsUsingRegistry = function(self)
        _origUpdate(self)
    end
end


function Library:ApplyPrimordialTheme()
    Library.FontColor = Color3.fromRGB(245, 245, 250)
    Library.MainColor = Color3.fromRGB(40, 40, 48)
    Library.BackgroundColor = Color3.fromRGB(30, 30, 38)
    Library.AccentColor = Color3.fromRGB(220, 150, 180)
    Library.OutlineColor = Color3.fromRGB(55, 55, 65)
    Library.RiskColor = Color3.fromRGB(255, 50, 50)
    Library.AccentColorDark = Library:GetDarkerColor(Library.AccentColor)
    Library.GlassEnabled = true
    Library.GlassTransparency = 0.52
    Library.OuterGlassTransparency = 0.58
    pcall(function() Library:UpdateColorsUsingRegistry() end)
    task.defer(function()
        pcall(function() Library:SetGlass(Library.GlassEnabled, Library.GlassTransparency or 0.55) end)
        pcall(function() Library:UpdateColorsUsingRegistry() end)
    end)
    pcall(function()
        if Library.WindowOuter then
            Library.WindowOuter.BackgroundTransparency = Library.OuterGlassTransparency
            Library.WindowOuter.BackgroundColor3 = Library.BackgroundColor
        end
        if Library.WindowInner then
            Library.WindowInner.BackgroundTransparency = Library.GlassTransparency
            Library.WindowInner.BackgroundColor3 = Library.MainColor
        end
    end)
    pcall(function() Library:UpdateBlur() end)
end

function Library:SetGlass(Enabled, Transparency)
    if type(Enabled) == "boolean" then
        Library.GlassEnabled = Enabled
    else
        Library.GlassEnabled = Enabled ~= false
    end
    if type(Transparency) == "number" then
        Library.GlassTransparency = math.clamp(Transparency, 0, 0.92)
    end
    Library.GlassTransparency = Library.GlassTransparency or 0.55
    local on = Library.GlassEnabled == true
    local t = Library.GlassTransparency
    local L1 = on and math.clamp(t + 0.12, 0, 0.93) or 0
    local L2 = on and math.clamp(t, 0, 0.88) or 0
    local L3 = on and math.clamp(t * 0.55, 0, 0.5) or 0
    Library.OuterGlassTransparency = L1
    Library._GlassLayer1 = L1
    Library._GlassLayer2 = L2
    Library._GlassLayer3 = L3
    pcall(function()
        if Library.WindowOuter then
            Library.WindowOuter.BackgroundColor3 = Library.BackgroundColor
            Library.WindowOuter.BackgroundTransparency = L1
        end
        if Library.WindowInner then
            Library.WindowInner.BackgroundColor3 = Library.MainColor
            Library.WindowInner.BackgroundTransparency = L2
        end
        if not Library.ScreenGui then return end
        for _, d in ipairs(Library.ScreenGui:GetDescendants()) do
            if d:IsA("Frame") or d:IsA("ScrollingFrame") then
                local nm = d.Name or ""
                if nm:find("Fill") or nm:find("Accent") or nm:find("Corner") or nm:find("Cursor") or nm:find("Indicator") or nm:find("Logo") then
                    -- keep solid / logo
                elseif d == Library.WindowOuter then
                    d.BackgroundTransparency = L1
                elseif d == Library.WindowInner then
                    d.BackgroundTransparency = L2
                elseif nm == "TabBarOuter" or nm == "TabBarInner" then
                    d.BackgroundTransparency = on and math.min(L3, 0.15) or 0
                    d.BackgroundColor3 = Library.BackgroundColor
                elseif nm == "TabArea" then
                    d.BackgroundTransparency = 1
                elseif d.Parent and d.Parent.Name == "TabArea" then
                    d.BackgroundTransparency = 0
                    d.BackgroundColor3 = Library.BackgroundColor
                elseif nm == "MainSectionOuter" or nm == "MainSectionInner" or nm == "TabContainer" or nm == "Inner" then
                    d.BackgroundTransparency = L2
                else
                    local reg = Library.RegistryMap[d]
                    if reg and reg.Properties then
                        local bg = reg.Properties.BackgroundColor3
                        if bg == "BackgroundColor" then
                            d.BackgroundColor3 = Library.BackgroundColor
                            d.BackgroundTransparency = L3
                        elseif bg == "MainColor" then
                            d.BackgroundTransparency = math.min(L3, 0.35)
                        end
                    elseif on and d.BackgroundTransparency < 0.05 and d.BorderSizePixel == 0 and d.AbsoluteSize.Y >= 8 then
                        d.BackgroundTransparency = math.min(L3, 0.28)
                    end
                end
            end
        end
        if on then
            Library.UseBlur = true
            Library.BlurSize = math.clamp(Library.BlurSize or 38, 14, 56)
            Library.UseDarken = true
            Library.DarkenAmount = math.clamp(Library.DarkenAmount or 48, 15, 80)
            if Library.Toggled then
                pcall(function() Library:UpdateBlur() end)
            end
        end
    end)
end

function Library:ReapplyGlass()
    Library.GlassEnabled = Library.GlassEnabled ~= false
    Library.GlassTransparency = Library.GlassTransparency or 0.55
    Library:SetGlass(Library.GlassEnabled, Library.GlassTransparency)
end



function Library:_GlassLayerMix1(base)
    base = tonumber(base) or Library.GlassTransparency or 0.55
    if not Library.GlassEnabled then return 0 end
    return math.clamp(base * (0.18), 0, 0.95)
end

function Library:_GlassLayerMix2(base)
    base = tonumber(base) or Library.GlassTransparency or 0.55
    if not Library.GlassEnabled then return 0 end
    return math.clamp(base * (0.21), 0, 0.95)
end

function Library:_GlassLayerMix3(base)
    base = tonumber(base) or Library.GlassTransparency or 0.55
    if not Library.GlassEnabled then return 0 end
    return math.clamp(base * (0.24), 0, 0.95)
end

function Library:_GlassLayerMix4(base)
    base = tonumber(base) or Library.GlassTransparency or 0.55
    if not Library.GlassEnabled then return 0 end
    return math.clamp(base * (0.27), 0, 0.95)
end

