-- Small live stud / position HUD (same glass style)
function Library:CreateLiveStudUI(Info)
    Info = Info or {}
    local Title = tostring(Info.Title or "RCLR")
    local Side = Info.Side or "Left"
    local Rate = tonumber(Info.UpdateRate) or 0.1
    local W, H = 168, 96

    pcall(function()
        if Library.LiveStudUI and Library.LiveStudUI.Destroy then Library.LiveStudUI:Destroy() end
    end)

    local Gui = Instance.new("ScreenGui")
    Gui.Name = "RCLR_LiveStud"
    Gui.ResetOnSpawn = false
    Gui.DisplayOrder = 60
    pcall(function() ProtectGui(Gui) end)
    pcall(function() Gui.Parent = CoreGui end)
    if not Gui.Parent then
        Gui.Parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") or CoreGui
    end

    local Frame = Instance.new("Frame")
    Frame.BackgroundColor3 = Library.BackgroundColor or Color3.fromRGB(16, 16, 20)
    Frame.BackgroundTransparency = 0.08
    Frame.BorderSizePixel = 0
    Frame.Size = UDim2.fromOffset(W, H)
    Frame.Position = Side == "Right" and UDim2.new(1, -(W + 12), 0, 90) or UDim2.new(0, 12, 0, 90)
    Frame.ZIndex = 80
    Frame.Parent = Gui
    Instance.new("UICorner", Frame).CornerRadius = UDim.new(0, 8)

    local st = Instance.new("UIStroke")
    st.Color = Library.OutlineColor or Color3.fromRGB(50, 50, 58)
    st.Transparency = 0.2
    st.Parent = Frame

    local top = Instance.new("Frame")
    top.BackgroundColor3 = Library.AccentColor or Color3.fromRGB(220, 150, 180)
    top.BorderSizePixel = 0
    top.Size = UDim2.new(1, 0, 0, 2)
    top.ZIndex = 81
    top.Parent = Frame

    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Position = UDim2.fromOffset(10, 8)
    title.Size = UDim2.new(1, -20, 0, 14)
    title.Font = Enum.Font.Code
    title.TextSize = 13
    title.TextColor3 = Color3.fromRGB(255, 255, 255)
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Text = Title
    title.ZIndex = 82
    title.Parent = Frame

    local function axis(y, name, col)
        local t = Instance.new("Frame")
        t.BackgroundColor3 = col
        t.BorderSizePixel = 0
        t.Position = UDim2.fromOffset(10, y)
        t.Size = UDim2.fromOffset(3, 12)
        t.ZIndex = 82
        t.Parent = Frame
        Instance.new("UICorner", t).CornerRadius = UDim.new(1, 0)
        local a = Instance.new("TextLabel")
        a.BackgroundTransparency = 1
        a.Position = UDim2.fromOffset(18, y - 1)
        a.Size = UDim2.fromOffset(16, 14)
        a.Font = Enum.Font.Code
        a.TextSize = 12
        a.TextColor3 = Color3.fromRGB(230, 230, 235)
        a.TextXAlignment = Enum.TextXAlignment.Left
        a.Text = name
        a.ZIndex = 82
        a.Parent = Frame
        local v = Instance.new("TextLabel")
        v.BackgroundTransparency = 1
        v.Position = UDim2.new(1, -78, 0, y - 1)
        v.Size = UDim2.fromOffset(70, 14)
        v.Font = Enum.Font.Code
        v.TextSize = 12
        v.TextColor3 = Color3.fromRGB(230, 230, 235)
        v.TextXAlignment = Enum.TextXAlignment.Right
        v.Text = "0"
        v.ZIndex = 82
        v.Parent = Frame
        return v
    end

    local xV = axis(30, "X", Library.AccentColor or Color3.fromRGB(230, 90, 100))
    local yV = axis(50, "Y", Color3.fromRGB(100, 210, 130))
    local zV = axis(70, "Z", Color3.fromRGB(100, 155, 240))

    pcall(function() Library:MakeDraggable(Frame, 28, false) end)

    local acc = 0
    local conn = RunService.Heartbeat:Connect(function(dt)
        acc += dt
        if acc < Rate then return end
        acc = 0
        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if hrp then
            local p = hrp.Position
            xV.Text = string.format("%.0f", p.X)
            yV.Text = string.format("%.0f", p.Y)
            zV.Text = string.format("%.0f", p.Z)
        else
            xV.Text, yV.Text, zV.Text = "---", "---", "---"
        end
    end)
    table.insert(Library.Signals, conn)

    local API = {}
    function API:SetTitle(t) title.Text = tostring(t or "") end
    function API:SetVisible(v) Frame.Visible = not not v; Gui.Enabled = not not v end
    function API:SetSide(side)
        Frame.Position = side == "Right" and UDim2.new(1, -(W + 12), 0, Frame.Position.Y.Offset) or UDim2.new(0, 12, 0, Frame.Position.Y.Offset)
    end
    function API:Destroy()
        pcall(function() conn:Disconnect() end)
        pcall(function() Gui:Destroy() end)
        if Library.LiveStudUI == API then Library.LiveStudUI = nil end
    end
    function API:GetGui() return Gui end
    function API:GetFrame() return Frame end
    Library.LiveStudUI = API
    return API
end

function Library:ToggleLiveStud(Visible)
    if Library.LiveStudUI then
        Library.LiveStudUI:SetVisible(Visible)
    end
end

function Library:SetLiveStudTitle(Title)
    if Library.LiveStudUI then
        Library.LiveStudUI:SetTitle(Title)
    end
end






function Library:SetFontFace(FontName)
    local f = Enum.Font[FontName] or Enum.Font.Code
    Library.Font = f
    pcall(function()
        if Library.ScreenGui then
            for _, d in ipairs(Library.ScreenGui:GetDescendants()) do
                if d:IsA('TextLabel') or d:IsA('TextButton') or d:IsA('TextBox') then
                    d.Font = f
                end
            end
        end
    end)
end

