    local t = {}
    for name in pairs(Library.Fonts) do
        table.insert(t, name)
    end
    table.sort(t)
    return t
end

function Library:ApplyFontToGui(gui, font)
    if not gui then return end
    font = font or Library.Font
    for _, d in ipairs(gui:GetDescendants()) do
        if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
            pcall(function() d.Font = font end)
        end
    end
end

function Library:SetFontFace(name)
    local f = Library.Fonts[name] or Enum.Font[name] or Library.Font or Enum.Font.Code
    Library.Font = f
    pcall(function()
        if Library.ScreenGui then Library:ApplyFontToGui(Library.ScreenGui, f) end
    end)
    pcall(function()
        if Library.LiveStudUI and Library.LiveStudUI.GetGui then
            local g = Library.LiveStudUI:GetGui()
            if g then Library:ApplyFontToGui(g, f) end
        end
    end)
end

