function Library:ApplyThemePreset(name)
    local data = Library.ThemePresets[name]
    if not data then return false end
    if data.FontColor then Library.FontColor = data.FontColor end
    if data.MainColor then Library.MainColor = data.MainColor end
    if data.BackgroundColor then Library.BackgroundColor = data.BackgroundColor end
    if data.AccentColor then
        Library.AccentColor = data.AccentColor
        if Library.GetDarkerColor then
            Library.AccentColorDark = Library:GetDarkerColor(data.AccentColor)
        end
    end
    if data.OutlineColor then Library.OutlineColor = data.OutlineColor end
    pcall(function() Library:UpdateColorsUsingRegistry() end)
    task.defer(function()
        pcall(function() Library:ReapplyGlass() end)
    end)
    return true
end

function Library:GetThemePresetNames()
    local t = {}
    for n in pairs(Library.ThemePresets) do table.insert(t, n) end
    table.sort(t)
    return t
end

-- Animation helpers
function Library:Tween(obj, ti, props)
    if not obj then return end
    local tw = TweenService:Create(obj, ti, props)
    tw:Play()
    return tw
end

function Library:FadeIn(frame, t)
    t = t or 0.2
    if not frame then return end
    frame.Visible = true
    local start = frame.BackgroundTransparency
    frame.BackgroundTransparency = 1
    Library:Tween(frame, TweenInfo.new(t, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        BackgroundTransparency = start
    })
end

function Library:FadeOut(frame, t, hide)
    t = t or 0.2
    if not frame then return end
    Library:Tween(frame, TweenInfo.new(t, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
        BackgroundTransparency = 1
    }).Completed:Connect(function()
        if hide then frame.Visible = false end
    end)
end

function Library:ScalePop(frame, t)
    t = t or 0.18
    if not frame then return end
    local size = frame.Size
    frame.Size = UDim2.fromOffset(math.max(10, size.X.Offset * 0.92), math.max(10, size.Y.Offset * 0.92))
    Library:Tween(frame, TweenInfo.new(t, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Size = size })
end

-- Watermark
function Library:CreateWatermark(text)
    pcall(function()
        if Library._WatermarkGui then Library._WatermarkGui:Destroy() end
    end)
    local gui = Instance.new("ScreenGui")
    gui.Name = "LuaX_Watermark"
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 40
    pcall(function() ProtectGui(gui) end)
    gui.Parent = CoreGui
    local f = Instance.new("TextLabel")
    f.BackgroundColor3 = Library.BackgroundColor or Color3.fromRGB(20,20,24)
    f.BackgroundTransparency = 0.25
    f.BorderSizePixel = 0
    f.Position = UDim2.fromOffset(12, 12)
    f.Size = UDim2.fromOffset(220, 24)
    f.Font = Library.Font or Enum.Font.Code
    f.TextSize = 14
    f.TextColor3 = Library.FontColor or Color3.fromRGB(255,255,255)
    f.Text = text or "RCLR Lua"
    f.Parent = gui
    Instance.new("UICorner", f).CornerRadius = UDim.new(0, 4)
    Library._WatermarkGui = gui
    return {
        SetText = function(_, t) f.Text = tostring(t) end,
        Destroy = function() gui:Destroy() end,
        SetVisible = function(_, v) gui.Enabled = not not v end,
    }
end

-- FPS counter
function Library:CreateFPSCounter()
    pcall(function()
        if Library._FPSGui then Library._FPSGui:Destroy() end
    end)
    local gui = Instance.new("ScreenGui")
    gui.Name = "LuaX_FPS"
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 41
    pcall(function() ProtectGui(gui) end)
    gui.Parent = CoreGui
    local f = Instance.new("TextLabel")
    f.BackgroundTransparency = 0.3
    f.BackgroundColor3 = Color3.fromRGB(15,15,18)
    f.BorderSizePixel = 0
    f.Position = UDim2.new(1, -90, 0, 12)
    f.Size = UDim2.fromOffset(78, 22)
    f.Font = Enum.Font.Code
    f.TextSize = 13
    f.TextColor3 = Color3.fromRGB(200, 255, 200)
    f.Text = "FPS: --"
    f.Parent = gui
    Instance.new("UICorner", f).CornerRadius = UDim.new(0, 4)
    local frames, acc = 0, 0
    local conn = RunService.RenderStepped:Connect(function(dt)
        frames += 1
        acc += dt
        if acc >= 0.5 then
            f.Text = string.format("FPS: %d", math.floor(frames / acc + 0.5))
            frames, acc = 0, 0
        end
    end)
    table.insert(Library.Signals, conn)
    Library._FPSGui = gui
    return {
        Destroy = function()
            pcall(function() conn:Disconnect() end)
            gui:Destroy()
        end,
        SetVisible = function(_, v) gui.Enabled = not not v end,
    }
end

-- Notify queue helpers
Library._NotifyQueue = Library._NotifyQueue or {}
function Library:NotifySuccess(msg, t)
    return Library:Notify(tostring(msg), t or 4)
end
function Library:NotifyError(msg, t)
    return Library:Notify("[!] " .. tostring(msg), t or 5)
end
function Library:NotifyInfo(msg, t)
    return Library:Notify(tostring(msg), t or 4)
end

-- Utility
function Library:IsMobile()
    return InputService.TouchEnabled and not InputService.KeyboardEnabled
end

function Library:GetScreenSize()
    local cam = workspace.CurrentCamera
    if cam then return cam.ViewportSize end
    return Vector2.new(1920, 1080)
end

function Library:SafePlayer()
    return LocalPlayer
end

function Library:SafeCharacter()
    return LocalPlayer and LocalPlayer.Character
end

function Library:SafeHRP()
    local c = Library:SafeCharacter()
    return c and c:FindFirstChild("HumanoidRootPart")
end

function Library:SafeHumanoid()
    local c = Library:SafeCharacter()
    return c and c:FindFirstChildOfClass("Humanoid")
end


function Library:UtilClamp1(n, a, b)
    n = tonumber(n) or 0
    a = tonumber(a) or 0
    b = tonumber(b) or 1
    if n < a then return a end
    if n > b then return b end
    return n
end

function Library:UtilClamp2(n, a, b)
    n = tonumber(n) or 0
    a = tonumber(a) or 0
    b = tonumber(b) or 1
    if n < a then return a end
    if n > b then return b end
    return n
end

function Library:UtilClamp3(n, a, b)
