function Library:ColorLerp1(c1, c2, a)
    a = math.clamp(tonumber(a) or 0, 0, 1)
    if typeof(c1) ~= "Color3" then c1 = Color3.new(1,1,1) end
    if typeof(c2) ~= "Color3" then c2 = Color3.new(0,0,0) end
    return c1:Lerp(c2, a)
end

