function Library:SetGlassLayer(layer, amount)
    amount = math.clamp(tonumber(amount) or 0, 0, 1)
    if layer == 1 then Library._GlassLayer1 = amount
    elseif layer == 2 then Library._GlassLayer2 = amount
    elseif layer == 3 then Library._GlassLayer3 = amount
    else Library._GlassLayer4 = amount end
    Library:ReapplyGlass()
end

function Library:GetGlassState()
    return {
        Enabled = Library.GlassEnabled == true,
        Transparency = Library.GlassTransparency or 0,
        Layer1 = Library._GlassLayer1 or 0,
        Layer2 = Library._GlassLayer2 or 0,
        Layer3 = Library._GlassLayer3 or 0,
        Layer4 = Library._GlassLayer4 or 0,
    }
end

function Library:EnableGlass(amount)
    Library:SetGlass(true, amount or Library.GlassTransparency or 0.55)
end

function Library:DisableGlass()
    Library:SetGlass(false, 0)
end

function Library:ValidateOptionIndex1(idx)
    if type(idx) ~= "string" and type(idx) ~= "number" then
        return false
    end
    return true
end

function Library:DeepCopyTable1(t)
    if type(t) ~= "table" then return t end
    local n = {}
    for k, v in pairs(t) do
        if type(v) == "table" then
            n[k] = Library:DeepCopyTable1(v)
        else
            n[k] = v
        end
    end
    return n
end

