function Library:ScaleForMobile(size)
    if typeof(size) ~= "UDim2" then return size end
    if not Library:IsMobile() then return size end
    local vp = Library:GetScreenSize()
    local w = math.min(size.X.Offset, vp.X - 16)
    local h = math.min(size.Y.Offset, vp.Y - 48)
    return UDim2.fromOffset(w, h)
end

function Library:BindToggleKey(keyPickerOrString)
    Library.ToggleKeybind = keyPickerOrString
end

function Library:MapRange1(v, inMin, inMax, outMin, outMax)
    v = tonumber(v) or 0
    inMin = tonumber(inMin) or 0
    inMax = tonumber(inMax) or 1
    outMin = tonumber(outMin) or 0
    outMax = tonumber(outMax) or 1
    if inMax == inMin then return outMin end
    local a = (v - inMin) / (inMax - inMin)
    return outMin + (outMax - outMin) * a
end

