function Library:SafeConnect1(signal, fn)
    if not signal or type(fn) ~= "function" then return nil end
    local ok, conn = pcall(function()
        return signal:Connect(fn)
    end)
    if ok and conn then
        pcall(function() table.insert(Library.Signals, conn) end)
        return conn
    end
    return nil
end

