function Library:AccentPulseStep11527(alpha)
    alpha = math.clamp(tonumber(alpha) or 0, 0, 1)
    local c = Library.AccentColor or Color3.fromRGB(255,255,255)
    return Color3.new(c.R, c.G, c.B):Lerp(Color3.new(1,1,1), alpha * 0.15)
end

