function Library:SerializeColor3(c)
    if typeof(c) ~= "Color3" then return {1,1,1} end
    return {c.R, c.G, c.B}
end

function Library:DeserializeColor3(t)
    if typeof(t) == "Color3" then return t end
    if type(t) ~= "table" then return Color3.new(1,1,1) end
    local r,g,b = t[1] or t.R or 1, t[2] or t.G or 1, t[3] or t.B or 1
    if r > 1 or g > 1 or b > 1 then
        return Color3.fromRGB(r,g,b)
    end
    return Color3.new(r,g,b)
end

function Library:ExportThemeTable()
    return {
        FontColor = Library:SerializeColor3(Library.FontColor),
        MainColor = Library:SerializeColor3(Library.MainColor),
        BackgroundColor = Library:SerializeColor3(Library.BackgroundColor),
        AccentColor = Library:SerializeColor3(Library.AccentColor),
        OutlineColor = Library:SerializeColor3(Library.OutlineColor),
        GlassEnabled = Library.GlassEnabled,
        GlassTransparency = Library.GlassTransparency,
        Font = tostring(Library.Font),
    }
end

function Library:ImportThemeTable(data)
    if type(data) ~= "table" then return false end
    if data.FontColor then Library.FontColor = Library:DeserializeColor3(data.FontColor) end
    if data.MainColor then Library.MainColor = Library:DeserializeColor3(data.MainColor) end
    if data.BackgroundColor then Library.BackgroundColor = Library:DeserializeColor3(data.BackgroundColor) end
    if data.AccentColor then
        Library.AccentColor = Library:DeserializeColor3(data.AccentColor)
        if Library.GetDarkerColor then
            Library.AccentColorDark = Library:GetDarkerColor(Library.AccentColor)
        end
    end
    if data.OutlineColor then Library.OutlineColor = Library:DeserializeColor3(data.OutlineColor) end
    if data.GlassTransparency ~= nil then Library.GlassTransparency = data.GlassTransparency end
    if data.GlassEnabled ~= nil then Library.GlassEnabled = data.GlassEnabled end
    pcall(function() Library:UpdateColorsUsingRegistry() end)
    pcall(function() Library:ReapplyGlass() end)
    return true
end

function Library:FormatKeyName(name)
    name = tostring(name or "")
    if name == "RightControl" then return "RCTRL" end
    if name == "LeftControl" then return "LCTRL" end
    if name == "RightShift" then return "RSHIFT" end
    if name == "LeftShift" then return "LSHIFT" end
    if name == "RightAlt" then return "RALT" end
    if name == "LeftAlt" then return "LALT" end
    if name == "MouseButton1" or name == "MB1" then return "M1" end
    if name == "MouseButton2" or name == "MB2" then return "M2" end
    return name
end

function Library:GetMenuKeyName()
    local kb = Library.ToggleKeybind
    if type(kb) == "table" then
        return tostring(kb.Value or "RightControl")
    end
    if type(kb) == "string" then return kb end
    return "RightControl"
end

function Library:MakeFrameDraggable(frame, dragZone)
    if not frame then return end
    dragZone = dragZone or frame
    local dragging, start, startPos
    dragZone.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            start = input.Position
            startPos = frame.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)
    Library:GiveSignal(InputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            local d = input.Position - start
            frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
        end
    end))
end

