function Library:MeasureText1(text, size)
    text = tostring(text or "")
    size = tonumber(size) or Library.FontSize or 14
    local bounds = TextService:GetTextSize(text, size, Library.Font or Enum.Font.Code, Vector2.new(1000, 50))
    return bounds
end

