function Library:DisconnectAllSignals1()
    if type(Library.Signals) ~= "table" then return end
    for _, c in ipairs(Library.Signals) do
        pcall(function()
            if c and c.Disconnect then c:Disconnect() end
        end)
    end
    table.clear(Library.Signals)
end

