function Library:GetToggleValue1(idx)
    local Toggles = getgenv().Toggles
    if type(Toggles) ~= "table" then return nil end
    local t = Toggles[idx]
    if type(t) == "table" then return t.Value end
    return nil
end

function Library:SetToggleValue1(idx, val)
    local Toggles = getgenv().Toggles
    if type(Toggles) ~= "table" then return false end
    local t = Toggles[idx]
    if type(t) == "table" and type(t.SetValue) == "function" then
        pcall(function() t:SetValue(not not val) end)
        return true
    end
    return false
end

