function Library:OpenMenu()
    if not Library.Toggled then
        Library:Toggle()
    end
end

function Library:CloseMenu()
    if Library.Toggled then
        Library:Toggle()
    end
end

function Library:IsMenuOpen()
    return Library.Toggled == true
end

function Library:CornerPosition1(side)
    side = tostring(side or "Left")
    if side == "Right" then
        return UDim2.new(1, -13, 0, 14)
    elseif side == "BottomLeft" then
        return UDim2.new(0, 13, 1, -41)
    elseif side == "BottomRight" then
        return UDim2.new(1, -13, 1, -41)
    end
    return UDim2.fromOffset(13, 14)
end

