function Library:ScriptHelper1(payload)
    if type(payload) == "table" then
        return payload
    end
    if type(payload) == "string" then
        return { Text = payload }
    end
    return {}
end

function Library:EnsureNumber1(v, default)
    v = tonumber(v)
    if v == nil then return default or 0 end
    return v
end

function Library:EnsureBool1(v, default)
    if v == nil then return not not default end
    return not not v
end

function Library:EnsureString1(v, default)
    if v == nil then return tostring(default or "") end
    return tostring(v)
end

