function Library:SnapshotGlass1()
    return {
        Enabled = Library.GlassEnabled == true,
        Amount = Library.GlassTransparency or 0.55,
        Blur = Library.BlurSize or 32,
        Darken = Library.DarkenAmount or 40,
        Id = 1,
    }
end

function Library:RestoreGlass1(snap)
    if type(snap) ~= "table" then return end
    if snap.Blur then Library.BlurSize = snap.Blur end
    if snap.Darken then Library.DarkenAmount = snap.Darken end
    Library:SetGlass(snap.Enabled ~= false, snap.Amount or 0.55)
end

