function Library:PaintRegistryColor1(prop, color)
    if typeof(color) ~= "Color3" then return end
    if prop == "AccentColor" then
        Library.AccentColor = color
        if Library.GetDarkerColor then
            Library.AccentColorDark = Library:GetDarkerColor(color)
        end
    elseif prop == "MainColor" then
        Library.MainColor = color
    elseif prop == "BackgroundColor" then
        Library.BackgroundColor = color
    elseif prop == "OutlineColor" then
        Library.OutlineColor = color
    elseif prop == "FontColor" then
        Library.FontColor = color
    end
    pcall(function() Library:UpdateColorsUsingRegistry() end)
end

