-- RCLR Loading Screen Module (library-side, call is 1-3 lines in scripts)
Library.LoadingScreenConfig = Library.LoadingScreenConfig or {
    DefaultDuration = 1.5,
    DefaultTitle = "RCLR Lua",
    DefaultSubtitle = "Loading...",
    CardWidth = 320,
    CardHeight = 140,
    AccentStroke = 0.35,
}

function Library:GetLoadingDefaults()
    return {
        Title = Library.LoadingScreenConfig.DefaultTitle,
        Subtitle = Library.LoadingScreenConfig.DefaultSubtitle,
        Duration = Library.LoadingScreenConfig.DefaultDuration,
        Steps = { "Initializing", "UI", "Themes", "Glass", "Ready" },
    }
end

function Library:_LoadingMakeGui()
    local Gui = Instance.new("ScreenGui")
    Gui.Name = "RCLR_LoadingScreen"
    Gui.ResetOnSpawn = false
    Gui.IgnoreGuiInset = true
    Gui.DisplayOrder = 5000
    Gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    pcall(function() ProtectGui(Gui) end)
    pcall(function() Gui.Parent = CoreGui end)
    if not Gui.Parent then
        local lp = game:GetService("Players").LocalPlayer
        Gui.Parent = lp and lp:FindFirstChildOfClass("PlayerGui") or CoreGui
    end
    return Gui
end

function Library:_LoadingMakeDim(parent)
    local Dim = Instance.new("Frame")
    Dim.Name = "Dim"
    Dim.BackgroundColor3 = Color3.fromRGB(4, 4, 8)
    Dim.BackgroundTransparency = 0.18
    Dim.BorderSizePixel = 0
    Dim.Size = UDim2.fromScale(1, 1)
    Dim.Parent = parent
    return Dim
end

function Library:_LoadingMakeCard(parent)
    local cfg = Library.LoadingScreenConfig
    local Card = Instance.new("Frame")
    Card.Name = "Card"
    Card.AnchorPoint = Vector2.new(0.5, 0.5)
    Card.Position = UDim2.fromScale(0.5, 0.5)
    Card.Size = UDim2.fromOffset(cfg.CardWidth or 320, cfg.CardHeight or 140)
    Card.BackgroundColor3 = Library.MainColor or Color3.fromRGB(28, 28, 34)
    Card.BackgroundTransparency = 0.06
    Card.BorderSizePixel = 0
    Card.Parent = parent
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, 12)
    c.Parent = Card
    local st = Instance.new("UIStroke")
    st.Color = Library.AccentColor or Color3.fromRGB(220, 150, 180)
    st.Transparency = cfg.AccentStroke or 0.35
    st.Thickness = 1.2
    st.Parent = Card
    return Card
end

function Library:_LoadingMakeTitle(parent, text)
    local t = Instance.new("TextLabel")
    t.Name = "Title"
    t.BackgroundTransparency = 1
    t.Position = UDim2.fromOffset(18, 16)
    t.Size = UDim2.new(1, -36, 0, 26)
    t.Font = Library.Font or Enum.Font.Code
    t.TextSize = 18
    t.TextColor3 = Library.FontColor or Color3.fromRGB(255, 255, 255)
    t.TextXAlignment = Enum.TextXAlignment.Left
    t.Text = tostring(text)
    t.Parent = parent
    return t
end

function Library:_LoadingMakeStep(parent, text)
    local t = Instance.new("TextLabel")
    t.Name = "Step"
    t.BackgroundTransparency = 1
    t.Position = UDim2.fromOffset(18, 50)
    t.Size = UDim2.new(1, -36, 0, 20)
    t.Font = Library.Font or Enum.Font.Code
    t.TextSize = 14
    t.TextColor3 = Color3.fromRGB(165, 165, 180)
    t.TextXAlignment = Enum.TextXAlignment.Left
    t.Text = tostring(text)
    t.Parent = parent
    return t
end

function Library:_LoadingMakeBar(parent)
    local bg = Instance.new("Frame")
    bg.Name = "BarBg"
    bg.Position = UDim2.fromOffset(18, 100)
    bg.Size = UDim2.new(1, -36, 0, 10)
    bg.BackgroundColor3 = Color3.fromRGB(16, 16, 20)
    bg.BorderSizePixel = 0
    bg.Parent = parent
    local c1 = Instance.new("UICorner")
    c1.CornerRadius = UDim.new(1, 0)
    c1.Parent = bg
    local bar = Instance.new("Frame")
    bar.Name = "Bar"
    bar.Size = UDim2.new(0, 0, 1, 0)
    bar.BackgroundColor3 = Library.AccentColor or Color3.fromRGB(220, 150, 180)
    bar.BorderSizePixel = 0
    bar.Parent = bg
    local c2 = Instance.new("UICorner")
    c2.CornerRadius = UDim.new(1, 0)
    c2.Parent = bar
    return bar, bg
end

function Library:_LoadingTweenBar(bar, goal, t)
    local tw = TweenService:Create(bar, TweenInfo.new(t, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        Size = UDim2.new(goal, 0, 1, 0)
    })
    tw:Play()
    return tw
end

function Library:_LoadingFadeOut(dim, card, t)
    t = t or 0.28
    pcall(function()
        TweenService:Create(dim, TweenInfo.new(t), { BackgroundTransparency = 1 }):Play()
        TweenService:Create(card, TweenInfo.new(t), { BackgroundTransparency = 1 }):Play()
    end)
end


function Library:_LoadingStepName1(idx, steps)
    if type(steps) == "table" and steps[idx] then
        return tostring(steps[idx])
    end
    return "Step " .. tostring(idx)
end

function Library:_LoadingProgress1(i, n)
    n = math.max(tonumber(n) or 1, 1)
    i = math.clamp(tonumber(i) or 0, 0, n)
    return i / n
end

