function Library:_LoadingColorPulse1(alpha)
    alpha = math.clamp(tonumber(alpha) or 0, 0, 1)
    local c = Library.AccentColor or Color3.fromRGB(220, 150, 180)
    return c:Lerp(Color3.new(1, 1, 1), alpha * 0.2)
end

