function Library:ShowLoadingScreen(Info)
    Info = type(Info) == "table" and Info or {}
    local defaults = Library:GetLoadingDefaults()
    local Title = tostring(Info.Title or defaults.Title)
    local Subtitle = tostring(Info.Subtitle or defaults.Subtitle)
    local Duration = math.clamp(tonumber(Info.Duration) or defaults.Duration, 0.35, 10)
    local Steps = Info.Steps
    if type(Steps) ~= "table" or #Steps < 1 then
        Steps = defaults.Steps
    end

    local finished = false
    local Gui = Library:_LoadingMakeGui()
    local Dim = Library:_LoadingMakeDim(Gui)
    local Card = Library:_LoadingMakeCard(Dim)
    local TitleL = Library:_LoadingMakeTitle(Card, Title)
    local StepL = Library:_LoadingMakeStep(Card, Subtitle)
    local Bar = Library:_LoadingMakeBar(Card)

    local stepTime = Duration / math.max(#Steps, 1)
    task.spawn(function()
        for i, step in ipairs(Steps) do
            StepL.Text = tostring(step)
            local goal = i / #Steps
            local tw = Library:_LoadingTweenBar(Bar, goal, stepTime)
            if tw then
                pcall(function() tw.Completed:Wait() end)
            else
                task.wait(stepTime)
            end
        end
        Library:_LoadingFadeOut(Dim, Card, 0.28)
        task.wait(0.32)
        pcall(function() Gui:Destroy() end)
        finished = true
    end)

    return {
        Wait = function()
            while not finished and Gui.Parent do
                task.wait()
            end
        end,
        Destroy = function()
            finished = true
            pcall(function() Gui:Destroy() end)
        end,
        SetStep = function(_, text)
            pcall(function() StepL.Text = tostring(text) end)
        end,
        SetTitle = function(_, text)
            pcall(function() TitleL.Text = tostring(text) end)
        end,
    }
end


function Library:StartCustomCursor()
    -- ONE cursor only
    if Library.ShowCustomCursor == false then
        return
    end
    -- cleanup any old cursors / loops
    pcall(function()
        if Library._CursorConn then
            Library._CursorConn:Disconnect()
            Library._CursorConn = nil
        end
    end)
    pcall(function()
        if Library.ScreenGui then
            for _, c in ipairs(Library.ScreenGui:GetChildren()) do
                if c.Name == "RCLR_CustomCursor" then
                    c:Destroy()
                end
            end
        end
    end)
    if Library._CursorRunning then
        return
    end
    Library._CursorRunning = true
    task.spawn(function()
        local State = InputService.MouseIconEnabled
        local Cursor = Instance.new("ImageLabel")
        Cursor.Name = "RCLR_CustomCursor"
        Cursor.Image = "rbxassetid://4292970642"
        Cursor.BackgroundTransparency = 1
        Cursor.ZIndex = 250
        Cursor.Size = UDim2.fromOffset(18, 18)
        Cursor.Rotation = -45
        Cursor.Visible = true
        if Library.ScreenGui then
            Cursor.Parent = Library.ScreenGui
        end
        InputService.MouseIconEnabled = false
        local conn
        conn = RunService.Heartbeat:Connect(function()
            if Library.ShowCustomCursor == false or not Library.ScreenGui or not Library.ScreenGui.Parent then
                InputService.MouseIconEnabled = State
                pcall(function() Cursor:Destroy() end)
                if conn then conn:Disconnect() end
                Library._CursorConn = nil
                Library._CursorRunning = false
                return
            end
            if not Cursor.Parent then
                Cursor.Parent = Library.ScreenGui
            end
            if not Library.Toggled then
                Cursor.Visible = false
                InputService.MouseIconEnabled = true
                return
            end
            InputService.MouseIconEnabled = false
            Cursor.Visible = true
            local m = InputService:GetMouseLocation()
            Cursor.Position = UDim2.fromOffset(m.X - 2, m.Y - 2)
        end)
        Library._CursorConn = conn
        table.insert(Library.Signals, conn)
    end)
end


-- RCLR Sounds
Library.SoundsEnabled = true
Library.Sounds = Library.Sounds or {
    Toggle = "rbxassetid://12221967",
    Button = "rbxassetid://12221967",
    Slider = "rbxassetid://12222225",
    Dropdown = "rbxassetid://12222208",
    Tab = "rbxassetid://12222208",
    Open = "rbxassetid://12221967",
    Close = "rbxassetid://12222225",
    Notify = "rbxassetid://12222225",
}

function Library:SetSound(name, assetId)
    if type(name) ~= "string" then return end
    Library.Sounds = Library.Sounds or {}
    Library.Sounds[name] = tostring(assetId)
end

function Library:PlaySound(name, volume)
    if Library.SoundsEnabled == false then return end
    local id = Library.Sounds and Library.Sounds[name]
    if not id or id == "" then return end
    pcall(function()
        local s = Instance.new("Sound")
        s.SoundId = id
        s.Volume = tonumber(volume) or 0.35
        s.PlayOnRemove = false
        s.Parent = CoreGui
        s:Play()
        task.delay(2, function()
            pcall(function() s:Destroy() end)
        end)
    end)
end

function Library:SetSoundsEnabled(on)
    Library.SoundsEnabled = on ~= false
end

-- RCLR Logo behind UI (sides visible, hides when menu closed)
function Library:CreateLogo(Info)
    Info = Info or {}
    pcall(function()
        if Library._LogoGui then Library._LogoGui:Destroy() end
    end)
    local text = tostring(Info.Text or "RCLR")
    local gui = Instance.new("ScreenGui")
    gui.Name = "RCLR_Logo"
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 5
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    pcall(function() ProtectGui(gui) end)
    pcall(function() gui.Parent = CoreGui end)
    if not gui.Parent then
        gui.Parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") or CoreGui
    end

    local function makeSide(side)
        local f = Instance.new("TextLabel")
        f.Name = "Logo_" .. side
        f.BackgroundTransparency = 1
        f.Font = Enum.Font.GothamBold
        f.Text = text
        f.TextSize = tonumber(Info.TextSize) or 42
        f.TextColor3 = Library.AccentColor or Color3.fromRGB(220, 150, 180)
        f.TextTransparency = 0.55
        f.TextStrokeTransparency = 0.7
        f.ZIndex = 1
        f.Size = UDim2.fromOffset(120, 50)
        if side == "Left" then
            f.AnchorPoint = Vector2.new(0, 0.5)
            f.Position = UDim2.new(0, 18, 0.5, 0)
            f.TextXAlignment = Enum.TextXAlignment.Left
        else
            f.AnchorPoint = Vector2.new(1, 0.5)
            f.Position = UDim2.new(1, -18, 0.5, 0)
            f.TextXAlignment = Enum.TextXAlignment.Right
        end
        f.Parent = gui
        return f
    end

    local left = makeSide("Left")
    local right = makeSide("Right")
    Library._LogoGui = gui
    Library._LogoLeft = left
    Library._LogoRight = right

    local function sync()
        local show = Library.Toggled == true
        gui.Enabled = show
        left.TextColor3 = Library.AccentColor or left.TextColor3
        right.TextColor3 = Library.AccentColor or right.TextColor3
    end
    sync()
    Library._LogoSync = sync
    return {
        SetText = function(_, t)
            left.Text = tostring(t)
            right.Text = tostring(t)
        end,
        SetVisible = function(_, v)
            gui.Enabled = not not v
        end,
        Destroy = function()
            pcall(function() gui:Destroy() end)
            Library._LogoGui = nil
        end,
        Sync = sync,
    }
end

function Library:UpdateLogoVisibility()
    if Library._LogoSync then
        pcall(Library._LogoSync)
    end
end



function Library:OnOptionActivated(kind)
    kind = kind or "Button"
    if kind == "Toggle" then
        Library:PlaySound("Toggle", 0.25)
    elseif kind == "Slider" then
        Library:PlaySound("Slider", 0.15)
    elseif kind == "Dropdown" then
        Library:PlaySound("Dropdown", 0.25)
    elseif kind == "Tab" then
        Library:PlaySound("Tab", 0.25)
    else
        Library:PlaySound("Button", 0.25)
    end
end

Library._IsLuaX = true
getgenv().LuaXLibrary = Library
if getgenv().Library == nil or (type(getgenv().Library) == "table" and getgenv().Library._IsLuaX) then
    getgenv().Library = Library
end
return Library
